sys_script_include.script:
var TemplateFlow = Class.create();
TemplateFlow.prototype = {
    initialize: function() {},

    // Button visibility
    canRetrieveFields: function(template) {
        var state = template.getValue('state');

        return state == 'draft';
    },

    canValidate: function(template) {
        return template.getValue('state') == 'mapping';
    },

    canPublish: function(template) {
        return template.getValue('state') == 'validated';
    },

    canEditAgain: function(template) {
        var state = template.getValue('state');

        return state != 'draft';
    },

    //  * Button actions
    retrieveFields: function(template) {
        var html = template.getValue('html_template');

        if (!html) {
            return {
                success: false,
                message: 'Please add HTML Template before retrieving fields.'
            };
        }

        var fieldUtil = new x_2162040_documate.fieldMappingUtils();
        fieldUtil.tempRetrive(template);

        template.setValue('state', 'mapping');
        template.update();

        return {
            success: true,
            message: 'Fields and sub templates retrieved successfully. Template moved to Mapping.'
        };
    },

    validateTemplate: function(template) {
        var errors = [];

        if (template.getValue('evaluate_condition_using_script') == '1' &&
            gs.nil(template.getValue('script_for_condition'))) {
            errors.push('Script for Condition is required when Evaluate Condition Using Script is checked.');
        }

        // Validate main template field mappings
        var fm = new GlideRecord('x_2162040_documate_field_mapping');
        fm.addQuery('template', template.getUniqueValue());
        fm.addQuery('mapping_context', 'template');
        fm.query();

        var fmcnt = 0;

        while (fm.next()) {
            var usesScript = fm.getValue('evaluate_value_using_script') == '1' ||
                fm.getValue('evaluate_value_using_script') == 'true';

            if ((usesScript && gs.nil(fm.getValue('script_value'))) ||
                (!usesScript && gs.nil(fm.getValue('field')))) {
                fmcnt++;
            }
        }

        if (fmcnt > 0) {
            errors.push('Field Mapping of ' + fmcnt + ' Template Fields is Required.');
        }

        // Validate subtemplates completion
        var subtemp = new GlideRecord('x_2162040_documate_sub_template');
        subtemp.addQuery('template', template.getUniqueValue());
        subtemp.query();

        var subcnt = 0;

        while (subtemp.next()) {
            if (subtemp.getValue('state') != 'complete') {
                subcnt++;
            }
        }

        if (subcnt > 0) {
            errors.push('Completion State of ' + subcnt + ' Sub Templates is Required.');
        }

        // Validate email templates whenever Send Email is checked
        if (template.getValue('send_email') == '1' || template.getValue('send_email') == 'true') {
            var email = new GlideRecord('x_2162040_documate_email');
            email.addQuery('template', template.getUniqueValue());
            email.query();

            var emailCount = 0;
            var invalidEmailCount = 0;
            var invalidEmailMappingCount = 0;

            while (email.next()) {
                emailCount++;

                if (gs.nil(email.getValue('mail_subject')) || gs.nil(email.getValue('mail_body'))) {
                    invalidEmailCount++;
                }

                var hasTo = !gs.nil(email.getValue('to_users')) ||
                    !gs.nil(email.getValue('to_groups')) ||
                    !gs.nil(email.getValue('to_other_recipients')) ||
                    email.getValue('evaluate_to_recipients_using_script') == '1' ||
                    email.getValue('evaluate_to_recipients_using_script') == 'true';

                if (!hasTo) {
                    errors.push('Email Template "' + email.getValue('name') + '" requires at least one To recipient source.');
                }

                var efm = new GlideRecord('x_2162040_documate_field_mapping');
                efm.addQuery('mapping_context', 'email_template');
                efm.addQuery('email_template', email.getUniqueValue());
                efm.query();

                while (efm.next()) {
                    var emailUsesScript = efm.getValue('evaluate_value_using_script') == '1' ||
                        efm.getValue('evaluate_value_using_script') == 'true';

                    if ((emailUsesScript && gs.nil(efm.getValue('script_value'))) ||
                        (!emailUsesScript && gs.nil(efm.getValue('field')))) {
                        invalidEmailMappingCount++;
                    }
                }
            }

            if (emailCount === 0) {
                errors.push('At least one Email Template is required when Send Email is checked.');
            }

            if (invalidEmailCount > 0) {
                errors.push(invalidEmailCount + ' Email Template(s) are missing Mail Subject or Mail Body.');
            }

            if (invalidEmailMappingCount > 0) {
                errors.push('Field Mapping of ' + invalidEmailMappingCount + ' Email Template Fields is required.');
            }
        }

        if (errors.length > 0) {
            return {
                success: false,
                message: errors.join('<br/>')
            };
        }

        template.setValue('state', 'validated');
        template.update();

        return {
            success: true,
            message: 'Template validated successfully.'
        };
    },

    publishTemplate: function(template) {
        if (template.getValue('state') != 'validated') {
            return {
                success: false,
                message: 'Only validated templates can be published.'
            };
        }

        var whenToRun = template.getValue('when_to_run');

        if (!whenToRun) {
            return {
                success: false,
                message: 'Please select When to run before publishing.'
            };
        }

        var automation = new global.TemplateAutomation();
        automation.deleteRule(template);
        automation.deleteSchedule(template);
        template.setValue('business_rule', '');
        template.setValue('scheduled_job', '');

        if (whenToRun == 'br') {
            var brSysId = automation.insertRule(template);

            if (!brSysId) {
                return {
                    success: false,
                    message: 'Template could not be published because Business Rule creation failed.'
                };
            }

            template.setValue('business_rule', brSysId);
        }

        if (whenToRun == 'schedule') {
            if (!template.getValue('run_type')) {
                return {
                    success: false,
                    message: 'Run Type is required for Scheduled Time.'
                };
            }

            if (!template.getValue('time')) {
                return {
                    success: false,
                    message: 'Time is required for Scheduled Time.'
                };
            }

            var scheduleSysId = automation.insertSchedule(template);

            if (!scheduleSysId) {
                return {
                    success: false,
                    message: 'Template could not be published because Scheduled Job creation failed.'
                };
            }

            template.setValue('scheduled_job', scheduleSysId);
        }

        template.setValue('state', 'published');
        template.update();

        if (whenToRun == 'br') {
            return {
                success: true,
                message: 'Template published successfully. Business Rule created.'
            };
        }

        return {
            success: true,
            message: 'Template published successfully. Scheduled Job created.'
        };
    },

    editAgain: function(template) {
        var automation = new global.TemplateAutomation();

        automation.deleteRule(template);
        automation.deleteSchedule(template);

        template.setValue('business_rule', '');
        template.setValue('scheduled_job', '');
        template.setValue('state', 'draft');
        template.update();

        return {
            success: true,
            message: 'Template moved back to Draft.'
        };
    },

    type: 'TemplateFlow'
};
